'use strict';
// Coche: Porsche 911 / 935 Turbo 1979 (Slantnose · Flat-6 Twin-Turbo · RWD)
// Modelo 3D de alta fidelidad cargado desde el archivo GLB original:
// - Carrocería completa con 51 nodos detallados (chasis, exterior, alerón, cabina, faros, badges).
// - Cuatro ruedas separadas con llantas de competición, neumáticos Continental slick y discos de freno ventilados.
// - Volante de carreras animado vinculado a la dirección.
// - Atlas de texturas de alta resolución (2048x2048) con todas las texturas PBR integradas.
(() => {

// Modelo 3D binario GLB 100% autocontenido en el archivo

// Atlas de texturas 2048x2048 integrado en Base64:
const PORSCHE_ATLAS_B64 = "data:image/png;base64,";
const PORSCHE_935_GLB_B64 = "";

WGSL["mat_car_911"] = `// Material del Porsche 911 / 935 Turbo 1979:
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let p = in.ext.xyz;
  let uv = in.uv;

  let tx = textureSample(tAtlas, sLin, uv);
  s.albedo = tx.rgb;

  if (id == 7u) {
    // Carrocería exterior: barniz brillante profundo
    s.metal = 0.08;
    s.rough = 0.16;
    s.coat = 1.0;
    s.ao = smoothstep(0.05, 0.35, p.y) * 0.35 + 0.65;
  } else if (id == 2u) {
    // Llantas de competición: aleación de aluminio pulido
    s.metal = 0.88;
    s.rough = 0.24;
    s.coat = 0.35;
  } else if (id == 4u) {
    // Neumáticos Continental slick de competición: goma mate
    s.metal = 0.0;
    s.rough = 0.68;
    s.ao = 0.88;
  } else if (id == 1u) {
    // Discos de freno de acero carbono ventilados
    s.metal = 0.85;
    s.rough = 0.32;
  } else if (id == 8u) {
    // Luces: freno dinámico, marcha atrás y faros delanteros
    let brk = O.p0.x;
    let rev = O.p0.y;
    let hl = O.p0.z;
    s.rough = 0.12;
    s.coat = 1.0;
    if (p.x < -1.8) {
      s.emissive = mix(0.15, 1.0, brk);
    } else if (p.x > 1.8) {
      s.emissive = hl * 0.95;
    }
  } else if (id == 9u) {
    // Interior / habitáculo / salpicadero
    s.rough = 0.65;
    s.ao = 0.75;
  } else {
    // Miscelánea / chasis
    s.rough = 0.45;
  }

  return s;
}
`;

function qrot(q, v) {
  const x = v[0], y = v[1], z = v[2];
  const qx = q[0], qy = q[1], qz = q[2], qw = q[3];
  const ix = qw * x + qy * z - qz * y;
  const iy = qw * y + qz * x - qx * z;
  const iz = qw * z + qx * y - qy * x;
  const iw = -qx * x - qy * y - qz * z;
  return [
    ix * qw + iw * -qx + iy * -qz - iz * -qy,
    iy * qw + iw * -qy + iz * -qx - ix * -qz,
    iz * qw + iw * -qz + ix * -qy - iy * -qx
  ];
}

const ATLAS = {
  6: { x: 0,    y: 0,    s: 1024 / 2048 }, // ext (1024x1024)
  1: { x: 1024, y: 0,    s: 512 / 2048 },  // wheel (512x512)
  2: { x: 1536, y: 0,    s: 512 / 2048 },  // misc (512x512)
  4: { x: 1024, y: 512,  s: 512 / 2048 },  // chassis (512x512)
  5: { x: 1536, y: 512,  s: 512 / 2048 },  // badges (512x512)
  7: { x: 0,    y: 1024, s: 512 / 2048 },  // lights (512x512)
  8: { x: 512,  y: 1024, s: 512 / 2048 },  // cab (512x512)
  0: { x: 1024, y: 1024, s: 256 / 2048 },  // rotor (256x256)
  3: { x: 1280, y: 1024, s: 256 / 2048 },  // tyre (256x256)
  9: { x: 0,    y: 0,    s: 0 },           // glass / transparent
};

const WHEEL_NODES = new Set([0, 1, 2, 39]);
const STEER_NODES = new Set([34]);

function p935UnpackGLB(buf, mb, gl, w, s) {
  const u8 = new Uint8Array(buf);
  const dv = new DataView(buf);
  const jsonLen = dv.getUint32(12, true);

  let jsonStr = '';
  if (typeof TextDecoder !== 'undefined') {
    jsonStr = new TextDecoder().decode(u8.subarray(20, 20 + jsonLen));
  } else {
    for (let i = 0; i < jsonLen; i++) jsonStr += String.fromCharCode(u8[20 + i]);
  }
  const gltf = JSON.parse(jsonStr);
  const binOffset = 20 + jsonLen + 8;

  function getAttr(accIdx, strideSize) {
    if (accIdx === undefined) return null;
    const acc = gltf.accessors[accIdx];
    const bv = gltf.bufferViews[acc.bufferView];
    const byteOffset = binOffset + (bv.byteOffset || 0) + (acc.byteOffset || 0);
    const stride = bv.byteStride ? bv.byteStride / 4 : strideSize;
    return {
      f32: new Float32Array(buf, byteOffset, acc.count * stride),
      stride,
      count: acc.count
    };
  }

  function getIndices(accIdx) {
    const acc = gltf.accessors[accIdx];
    const bv = gltf.bufferViews[acc.bufferView];
    const byteOffset = binOffset + (bv.byteOffset || 0) + (acc.byteOffset || 0);
    if (acc.componentType === 5123) {
      return new Uint16Array(buf, byteOffset, acc.count);
    } else if (acc.componentType === 5125) {
      return new Uint32Array(buf, byteOffset, acc.count);
    }
    return new Uint8Array(buf, byteOffset, acc.count);
  }

  gltf.nodes.forEach((node, nIdx) => {
    if (node.mesh === undefined) return;
    const mesh = gltf.meshes[node.mesh];
    const t = node.translation || [0, 0, 0];
    const r = node.rotation || [0, 0, 0, 1];
    const sc = node.scale || [1, 1, 1];

    const isWheel = WHEEL_NODES.has(nIdx);
    const isSteer = STEER_NODES.has(nIdx);

    if (isWheel && nIdx !== 39) return;

    mesh.primitives.forEach(prim => {
      const isGlass = prim.material === 9;
      const targetBuilder = isWheel ? w : (isSteer ? s : (isGlass ? gl : mb));

      const pos = getAttr(prim.attributes.POSITION, 3);
      const nrm = getAttr(prim.attributes.NORMAL, 3);
      const uv = getAttr(prim.attributes.TEXCOORD_0, 2);
      const idxs = getIndices(prim.indices);

      const matInfo = ATLAS[prim.material] || { x: 0, y: 0, s: 1 };
      const matId = prim.material !== undefined ? prim.material + 1 : 1;

      targetBuilder.mat(matId);
      const baseV = targetBuilder.nv;

      for (let i = 0; i < pos.count; i++) {
        const lx = pos.f32[i * pos.stride];
        const ly = pos.f32[i * pos.stride + 1];
        const lz = pos.f32[i * pos.stride + 2];

        let nx = nrm ? nrm.f32[i * nrm.stride] : 0;
        let ny = nrm ? nrm.f32[i * nrm.stride + 1] : 1;
        let nz = nrm ? nrm.f32[i * nrm.stride + 2] : 0;

        let u0 = uv ? uv.f32[i * uv.stride] : 0;
        let v0 = uv ? uv.f32[i * uv.stride + 1] : 0;

        const uAtlas = (u0 * (matInfo.s * 2048) + matInfo.x) / 2048;
        const vAtlas = (v0 * (matInfo.s * 2048) + matInfo.y) / 2048;

        let px, py, pz, normX, normY, normZ;

        if (isWheel) {
          px = -lz * 0.949025;
          py = ly * 0.949025;
          pz = lx * 0.949025;
          normX = -nz;
          normY = ny;
          normZ = nx;
        } else if (isSteer) {
          px = -lz;
          py = ly;
          pz = lx;
          normX = -nz;
          normY = ny;
          normZ = nx;
        } else {
          const rotP = qrot(r, [lx * sc[0], ly * sc[1], lz * sc[2]]);
          const wx = rotP[0] + t[0];
          const wy = rotP[1] + t[1];
          const wz = rotP[2] + t[2];

          const rotN = qrot(r, [nx / sc[0], ny / sc[1], nz / sc[2]]);
          const nlen = Math.hypot(rotN[0], rotN[1], rotN[2]) || 1;
          const wnx = rotN[0] / nlen;
          const wny = rotN[1] / nlen;
          const wnz = rotN[2] / nlen;

          px = wz;
          py = wy;
          pz = -wx;
          normX = wnz;
          normY = wny;
          normZ = -wnx;
        }

        targetBuilder.v(px, py, pz, normX, normY, normZ, uAtlas, vAtlas);
      }

      for (let i = 0; i < idxs.length; i += 3) {
        targetBuilder.tri(baseV + idxs[i], baseV + idxs[i + 1], baseV + idxs[i + 2]);
      }
    });
  });
}

function p935LoadAtlas() {
  const W = 2048, H = 2048;
  const tex = mkTex(W, H, 'rgba8unorm-srgb', TU.RT | TU.TB | TU.CD, { mipLevelCount: 7 });

  const initData = new Uint8Array(W * H * 4);
  initData.fill(220);
  G.dev.queue.writeTexture({ texture: tex }, initData, { bytesPerRow: W * 4 }, [W, H]);

  if (typeof Image !== 'undefined') {
    const img = new Image();
    img.src = (typeof PORSCHE_ATLAS_B64 !== 'undefined') ? PORSCHE_ATLAS_B64 : 'cars/porsche911/atlas.png';
    const loadPromise = new Promise(resolve => {
      img.onload = () => {
        if (typeof createImageBitmap !== 'undefined') {
          createImageBitmap(img).then(bmp => {
            G.dev.queue.copyExternalImageToTexture({ source: bmp }, { texture: tex }, [W, H]);
            genMips(tex, 'rgba8unorm-srgb');
            resolve();
          }).catch(resolve);
        } else {
          resolve();
        }
      };
      img.onerror = resolve;
    });
    if (R && R.pending) R.pending.push(loadPromise);
  }

  return tex;
}

const CAR = {
  id: 'porsche-911-1979',
  name: 'Porsche 911 / 935 Turbo',
  subtitle: '1979 Porsche 935 Slantnose · Flat-6 Twin-Turbo · RWD',
  specs: '1040 kg · 750 CV · Moby Dick Aero · Chasis Gr.5 Competición · RWD',
  accent: '#e8251e',
  physics: {
    m: 1040, Izz: 1720, L: 2.420, a: 1.240, b: 1.180, tw: 1.88, h: 0.38, R: 0.300,
    mu: 1.85, B: 11.5, C: 1.55, driveF: 0.0,
    gears: [2.05, 1.45, 1.08, 0.84], final: 3.88, rev: 3.1, eff: 0.94,
    cdA: 0.58, crr: 0.010, brakeF: 0.65, halfW: 0.98, front: 2.34, rear: 2.33,
    // Downforce aerodinámico de competición (gran alerón trasero Moby Dick + splitter delantero):
    clA: 1.15, aeroSplitF: 0.40,
    torqueBase: 380, torquePeak: 320, torqueDrop: 210, torquePeakStart: 0.65, torquePeakSpan: 5.8, torqueDropRpm: 7.2,
    shiftUpRpm: 7800, shiftDownRpm: 5600, revLimitRpm: 8200, maxRpm: 8400, idleRpm: 1100,
  },
  hud: { maxKmh: 350, maxRpm: 8.5, redlineRpm: 7.8 },
  wheelbase: 2.270, trackF: 1.762, trackR: 1.958, wheelR: 0.2856,
  hubs: [
    [1.362, 0.2856, -0.881],
    [1.362, 0.2856, 0.881],
    [-0.908, 0.2856, -0.979],
    [-0.908, 0.2856, 0.979]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0], slotSteer: 0,
  steerMat: m4(), tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_911', { src: 'mat_car_911', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();
    CAR.slotSteer = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const glass = CAR.glass = new GlassSet();

    const mb = new MeshBuilder(1 << 16);
    const gl = new MeshBuilder(1 << 14);
    const w = new MeshBuilder(1 << 14);
    const s = new MeshBuilder(1 << 12);

    let glbBuf = null;
    if (typeof atob !== 'undefined') {
      const bin = atob(PORSCHE_935_GLB_B64);
      const len = bin.length;
      const u8 = new Uint8Array(len);
      for (let i = 0; i < len; i++) u8[i] = bin.charCodeAt(i);
      glbBuf = u8.buffer;
    }

    if (glbBuf) {
      p935UnpackGLB(glbBuf, mb, gl, w, s);
    }

    CAR.tris = mb.ni / 3 + gl.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);
    glass.add_(gl.upload(), CAR.slotBody);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const sm = s.upload();
    CAR.tris += s.ni / 3;
    set.add(sm, CAR.slotSteer, 3);

    m4translate(CAR._t, 0.407, 0.712, -0.281);
    m4rotZ(CAR._t2, -22 * PI / 180);
    m4mul(CAR.steerMat, CAR._t, CAR._t2);

    const tex = p935LoadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });
    R.transparents.push(glass);

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0], steerWheelAngle = CAR.inp[1];
    const t = CAR._t2, t2 = CAR._t3;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
    objPrev(CAR.slotSteer).set(objModel(CAR.slotSteer));
    const ca = Math.cos(-steerWheelAngle), sa = Math.sin(-steerWheelAngle);
    t2.fill(0); t2[0] = 1; t2[5] = ca; t2[6] = sa; t2[9] = -sa; t2[10] = ca; t2[15] = 1;
    m4mul(t, CAR.steerMat, t2);
    m4mul(objModel(CAR.slotSteer), body, t);
  },
};

CARS.register(CAR);
})();
